/**
 * NASA Scientific Data Integrity & Provenance Tracking
 *
 * Enforces strict classification of all data into three mutually exclusive categories:
 * 1. REAL NASA DATA — actual observations or measurements collected by NASA missions/instruments.
 * 2. RESEARCH EVIDENCE — published studies, bio-experiments, and scientific findings from NASA repositories.
 * 3. SIMULATED DATA — educational values generated by our mission model.
 */

export const DATA_CATEGORIES = Object.freeze({
  REAL_NASA_DATA: 'REAL_NASA_DATA',
  RESEARCH_EVIDENCE: 'RESEARCH_EVIDENCE',
  LITERATURE_BENCHMARK: 'LITERATURE_BENCHMARK',
  SIMULATED_DATA: 'SIMULATED_DATA'
});

export const CATEGORY_BADGES = Object.freeze({
  [DATA_CATEGORIES.REAL_NASA_DATA]: {
    label: 'REAL NASA DATA — OBSERVATION',
    shortLabel: 'REAL NASA DATA',
    tagClass: 'tag-blue',
    description: 'Actual physical measurements or space weather events recorded by NASA spacecraft, detectors, or ground stations.'
  },
  [DATA_CATEGORIES.RESEARCH_EVIDENCE]: {
    label: 'RESEARCH EVIDENCE — NASA STUDY',
    shortLabel: 'RESEARCH EVIDENCE',
    tagClass: 'tag-purple',
    description: 'Peer-reviewed space biology studies, experimental results, and flight research from NASA repositories.'
  },
  [DATA_CATEGORIES.LITERATURE_BENCHMARK]: {
    label: 'PEER-REVIEWED LITERATURE BENCHMARK',
    shortLabel: 'LITERATURE BENCHMARK',
    tagClass: 'tag-outline',
    description: 'Published scientific literature summaries, flight data compendia, and external international missions used for comparative education.'
  },
  [DATA_CATEGORIES.SIMULATED_DATA]: {
    label: 'SIMULATED DATA — MISSION MODEL',
    shortLabel: 'SIMULATED DATA',
    tagClass: 'tag-amber',
    description: 'Educational values generated by the LunarBase simulator using documented illustrative engineering assumptions.'
  }
});

const REQUIRED_PROVENANCE_FIELDS = [
  'datasetName',
  'source',
  'sourceUrl',
  'retrievalTimestamp',
  'collectionPeriod',
  'spatialApplicability',
  'temporalApplicability',
  'units',
  'description',
  'limitations',
  'category'
];

/**
 * Validates a provenance metadata object.
 * @param {Object} provenance
 * @returns {Object} Validated provenance object
 */
export function validateProvenance(provenance) {
  if (!provenance || typeof provenance !== 'object' || Array.isArray(provenance)) {
    throw new TypeError('Provenance record must be a non-null object.');
  }

  const missing = REQUIRED_PROVENANCE_FIELDS.filter((field) => {
    const val = provenance[field];
    return val === undefined || val === null || val === '';
  });

  if (missing.length > 0) {
    throw new Error(`Provenance record is missing required fields: ${missing.join(', ')}`);
  }

  if (!Object.values(DATA_CATEGORIES).includes(provenance.category)) {
    throw new Error(`Invalid data category: "${provenance.category}". Must be one of: ${Object.values(DATA_CATEGORIES).join(', ')}`);
  }

  if (!/^https:\/\//i.test(provenance.sourceUrl)) {
    throw new Error(`Source URL must use HTTPS protocol: ${provenance.sourceUrl}`);
  }

  if (typeof provenance.units !== 'object' || Array.isArray(provenance.units)) {
    throw new TypeError('Provenance units must be a keyed object mapping measurement names to unit strings.');
  }

  return provenance;
}

/**
 * Creates a validated provenance metadata object.
 * @param {Object} fields
 * @returns {Object}
 */
export function createProvenanceRecord({
  datasetName,
  source,
  sourceUrl,
  retrievalTimestamp = new Date().toISOString(),
  collectionPeriod,
  spatialApplicability,
  temporalApplicability = collectionPeriod,
  units = {},
  description,
  limitations,
  category = DATA_CATEGORIES.REAL_NASA_DATA,
  instrument = null,
  mission = null,
  rawMetadata = null
}) {
  const record = {
    datasetName,
    source,
    sourceUrl,
    retrievalTimestamp,
    collectionPeriod,
    spatialApplicability,
    temporalApplicability,
    units,
    description,
    limitations,
    category,
    instrument,
    mission,
    rawMetadata
  };

  return validateProvenance(record);
}
